interface.definition:
a!localVariables(
  local!statusFilter,
  local!yearFilter,
  local!dppGroupFilter,
  local!levelFilter,
  local!specialityFilter,
  local!reasonFilter,
  local!paging: #"SYSTEM_SYSRULES_pagingInfo"(
    startIndex: 1,
    batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "askDetailId")
  ),
  local!coreAskPaging:#"SYSTEM_SYSRULES_pagingInfo"(
    startIndex: 1,
    batchSize: -1,
    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "version")
  ),
  local!coreASKFilterData: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
    refTypeId: {
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245536",
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245543",
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245550",
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245730"
    },
    returnCDT: true,
    isActive: true
  ),
  local!levelDropDown: property(
    index(
      local!coreASKFilterData,
      wherecontains(
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245550",
        tointeger(property(local!coreASKFilterData,"refTypeId",null))
      ),
      null
    ),
    "description",
    tostring(null)
  ),
  local!specialityDropDown: property(
    index(
      local!coreASKFilterData,
      wherecontains(
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245730",
        tointeger(property(local!coreASKFilterData,"refTypeId",null))
      ),
      null
    ),
    "description",
    tostring(null)
  ),
  local!reasonDropDown: property(
    index(
      local!coreASKFilterData,
      wherecontains(
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245543",
        tointeger(property(local!coreASKFilterData,"refTypeId",null))
      ),
      null
    ),
    "description",
    tostring(null)
  ),
  local!dppGroupFDropDown: property(
    index(
      local!coreASKFilterData,
      wherecontains(
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245536",
        tointeger(property(local!coreASKFilterData,"refTypeId",null))
      ),
      null
    ),
    "description",
    tostring(null)
  ),
  local!fYearDropDown: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6751857"(),
  local!coreData: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3235974"(
    fetchTotalCount: true,
    pagingInfo: local!coreAskPaging,
    fiscalYear: if(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!yearFilter),null,local!yearFilter),
    status: if(#"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!statusFilter),null,local!statusFilter),
    dppGroup: if(#"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!dppGroupFilter,),null,local!dppGroupFilter),
    level: if(#"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!levelFilter,),null,local!levelFilter),
    speciality: if(#"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!specialityFilter,),null,local!specialityFilter),
    reason: if(#"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!reasonFilter,),null,local!reasonFilter)
  ).data,
  local!getDistinctCoreASKs: #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(index(local!coreData, "askId", null)),
  local!filteredAsks: #"SYSTEM_SYSRULES_forEach"(
    items: local!getDistinctCoreASKs,
    expression: index(
      local!coreData,
      wherecontains(
        fv!item,
        tointeger(index(local!coreData, "askId", null))
      )[1],
      null
    ),

  ),
  local!askDetailIds:index(local!filteredAsks,"askDetailId",null),

  local!documentId,
  local!isError: false,
  {
    #"SYSTEM_SYSRULES_cardLayout"(
      marginBelow: "STANDARD",
      style: "ACCENT",
      showBorder: false,
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          align: "RIGHT",
          value: {
            #"SYSTEM_SYSRULES_richTextIcon"(
              icon: "refresh",
              linkStyle: "STANDALONE",
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: {
                  a!save(
                    {
                      local!statusFilter,
                      local!yearFilter,
                      local!dppGroupFilter,
                      local!levelFilter,
                      local!specialityFilter,
                      local!reasonFilter,
                      local!documentId
                    },
                    null
                  ),
                  a!save(local!isError, false)
                }
              )
            ),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: " Clear Filters",
              style: "STRONG",
              linkStyle: "STANDALONE",
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: {
                  a!save(
                    {
                      local!statusFilter,
                      local!yearFilter,
                      local!dppGroupFilter,
                      local!levelFilter,
                      local!specialityFilter,
                      local!reasonFilter,
                      local!documentId
                    },
                    null
                  ),
                  a!save(local!isError, false)
                }
              )
            )
          }
        ),
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5243124"(
          statusFilter:local!statusFilter,
          yearFilter: local!yearFilter,
          dppGroupFilter:local!dppGroupFilter,
          levelFilter:local!levelFilter,
          specialityFilter:local!specialityFilter,
          reasonFilter:local!reasonFilter,
          fYearDropDown:local!fYearDropDown,
          dppGroupFDropDown: local!dppGroupFDropDown,
          levelDropDown:local!levelDropDown,
          specialityDropDown:local!specialityDropDown,
          reasonDropDown:local!reasonDropDown,
          paging: local!paging,
          documentId: local!documentId,
        )
      }
    ),
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_ButtonLayout"(
              secondaryButtons: {
                #"SYSTEM_SYSRULES_ButtonWidget"(
                  label: "Go Back",
                  value:ri!chooseId,
                  saveInto: {
                    a!save(ri!chooseId,1),
                    a!save(
                      {
                        local!statusFilter,
                        local!yearFilter,
                        local!dppGroupFilter,
                        local!levelFilter,
                        local!specialityFilter,
                        local!reasonFilter,
                        local!documentId
                      },
                      null
                    )
                  }
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              marginBelow: "STANDARD",
              style: if(
                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(local!coreData, "data",{})),
                "STANDARD",
                "#00A36C"
              ),
              link: if(
                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(local!coreData, "data",{})),
                null,
                #"SYSTEM_SYSRULES_dynamicLink"(
                  saveInto: #"SYSTEM_SYSRULES_startProcess"(
                    processModel: #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5163467",
                    processParameters: {
                      yearFilter:local!yearFilter,
                      dppGroup:local!dppGroupFilter,
                      level:local!levelFilter,
                      statusFilter:local!statusFilter,
                      reason:local!reasonFilter,
                      speciality:local!specialityFilter,
                      exportType:#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3371522",
                      askDetailId:local!askDetailIds
                    },
                    onSuccess: {
                      a!save(
                        local!documentId,
                        fv!processInfo.pv.NewDocument
                      ),
                      a!save(local!isError,false)
                    },
                    onError: {
                      a!save(local!isError,true),
                      a!save(local!documentId, null)
                    }
                  )
                )
              ),
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  align: "CENTER",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "file-excel-o"
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "  Generate Excel Export",
                      style: "STRONG",
                    )
                  }
                )
              },
              shape: "SEMI_ROUNDED"
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              marginBelow: "STANDARD",
              style: "#0BDA51",
              link:#"SYSTEM_SYSRULES_documentDownloadLink"(
                document: local!documentId
              ),
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  align: "CENTER",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      linkStyle: "STANDALONE",
                      icon: "download"
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      text: " Download Excel Export",
                      style: "STRONG"
                    )
                  }
                ),
              },
              shape: "SEMI_ROUNDED"
            )
          },
          showWhen:#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              marginBelow: "STANDARD",
              style: "STANDARD",
              link:#"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: a!save(local!documentId,null)
              ),
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  align: "CENTER",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      linkStyle: "STANDALONE",
                      icon: "refresh"
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      text: " Reset",
                      style: "STRONG"
                    )
                  }
                )
              },
              shape: "SEMI_ROUNDED"
            )
          },
          showWhen:#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      showWhen: local!isError,
      marginBelow: "STANDARD",
      style: "ERROR",
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          align: "CENTER",
          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
            style: "STRONG",
            text: "There was an error exporting Core ASK details. Please clear filters and try again.",
            color: "NEGATIVE"
          )
        )
      }
    ),
    #"SYSTEM_SYSRULES_boxLayout"(
      label: "Core ASKs",
      style: "ACCENT",
      contents: #"SYSTEM_SYSRULES_gridField_v1"(
        labelPosition: "COLLAPSED",
        emptyGridMessage: "No Core ASKs Found",
        data: local!filteredAsks,
        refreshAlways: true,
        columns: {
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Request Number",
            sortField: "askId",
            value: #"SYSTEM_SYSRULES_richTextDisplayField"(
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: index(
                  split(
                    fv!row.dppGroup,
                    "–"
                  ),
                  1,
                  tointeger(null)
                ) & " - " & "FY"&right(fv!row.fyear,2)
              )
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "DPP Group",
            sortField: "dppGroup",
            value: fv!row.dppGroup
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Level",
            sortField: "levelNeed",
            value: if(
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.levelNeed),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
              fv!row.levelNeed
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Outgoing Resource",
            sortField: "outGoingResource",
            value: if(
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.outGoingResource),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
              fv!row.outGoingResource
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Reason",
            sortField: "needReason",
            value: if(
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.needReason),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
              fv!row.needReason
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Year",
            sortField: "fYear",
            value: fv!row.fYear
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Projected Start Date",
            sortField: "projectedStartDate",
            value: if(
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.projectedStartDate),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
              fv!row.projectedStartDate
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Retirement/ End Date",
            sortField: "endDate",
            value: if(
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.endDate),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
              fv!row.endDate
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "General/ Specialty",
            sortField: "generalSpecialityNeed",
            value: if(
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.generalSpecialityNeed),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
              fv!row.generalSpecialityNeed
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Role Posting",
            sortField: "rolePosting",
            value: if(
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.rolePosting),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
              fv!row.rolePosting
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Version",
            sortField: "version",
            value: #"SYSTEM_SYSRULES_richTextDisplayField"(
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: fv!row.version
              )
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Status",
            sortField: "statusId",
            value: #"SYSTEM_SYSRULES_richTextDisplayField"(
              value:#"SYSTEM_SYSRULES_richTextItem_v1"(
                text: fv!row.status
              )
            )
          ),
        },
        rowHeader: 1,
        pagingSaveInto: local!paging,
        spacing: "DENSE",
        borderStyle: "LIGHT",
        shadeAlternateRows: true(),initialSorts: #"SYSTEM_SYSRULES_sortInfo"(field: "askId")
      ),
      marginBelow: "STANDARD"
    )
  }
)
